// Probe — playtest phase (step 3). Deleted once .scratch/to_fix.md is written.
// collideBricks does not exist in game/neon.js yet: this stub reproduces the
// CURRENT frame() brick handling (kill + score, NO bounce) so that every case
// fails for its real reason, not for a missing import.
import { test } from 'node:test';
import assert from 'node:assert/strict';

import {
  collides,
  step,
  createState,
  ballSpeed,
  scoreForBrick,
  BALL_R,
  DOWN,
} from '../game/neon.js';

function collideBricks(state) {
  let broken = 0;
  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    if (collides(state.ball, brick)) {
      brick.alive = false;
      state.combo += 1;
      state.score += scoreForBrick(brick, state.combo);
      broken += 1;
    }
  }
  return broken;
}

function brickAt(state, row, col) {
  return state.bricks.find((b) => b.row === row && b.col === col);
}

// --- D1: no bounce at all ---------------------------------------------------

test('D1: ball hitting a brick bottom face is deflected down and pushed out', () => {
  const state = createState(1);
  const brick = brickAt(state, 4, 2); // x=164..236, y=160..180
  const cx = brick.x + brick.w / 2; // 200
  state.ball = {
    x: cx, y: brick.y + brick.h, r: BALL_R, vx: 0, vy: -260,
    px: cx, py: brick.y + brick.h + 15,
  };
  const broken = collideBricks(state);
  assert.equal(broken, 1);
  assert.equal(brick.alive, false);
  assert.equal(state.ball.vy, 260); // UP -> DOWN
  assert.equal(state.ball.y, brick.y + brick.h + BALL_R); // pushed out below
  assert.equal(collides(state.ball, brick), false);
});

// --- D2: sticky (flip without repositioning) --------------------------------

test('D2: after resolution the ball is fully outside the brick', () => {
  const state = createState(1);
  const brick = brickAt(state, 4, 4); // x=324..396, y=160..180
  state.ball = {
    x: brick.x + brick.w / 2, y: brick.y + 8, r: BALL_R, vx: 0, vy: -260,
    px: brick.x + brick.w / 2, py: brick.y + 18,
  };
  collideBricks(state);
  assert.equal(collides(state.ball, brick), false);
  assert.ok(state.ball.vy > 0, 'vy must point away from the brick');
});

// --- D3: face vs corner -----------------------------------------------------

test('D3: lateral hit flips vx, never vy', () => {
  const state = createState(1);
  const brick = brickAt(state, 4, 0); // x=4..76, y=160..180
  const cy = brick.y + brick.h / 2; // 170
  state.ball = {
    x: brick.x - 4, y: cy, r: BALL_R, vx: 260, vy: -50,
    px: brick.x - 15, py: cy,
  };
  collideBricks(state);
  assert.equal(state.ball.vx, -260);
  assert.equal(state.ball.vy, -50); // vertical component untouched
  assert.equal(collides(state.ball, brick), false);
});

test('D3: corner contact with equal penetration flips both axes', () => {
  const state = createState(1);
  const brick = brickAt(state, 4, 0); // x=4..76, y=160..180
  // Ball box overlaps the top-left corner by exactly 4px on each axis.
  state.ball = {
    x: brick.x - 3, y: brick.y - 3, r: BALL_R, vx: 130, vy: 260,
    px: brick.x - 3, py: brick.y - 3,
  };
  collideBricks(state);
  assert.equal(state.ball.vx, -130);
  assert.equal(state.ball.vy, -260);
  assert.equal(collides(state.ball, brick), false);
});

// --- D4: double inversion on a grid seam ------------------------------------

test('D4: ball squeezed between two stacked bricks flips vy exactly once', () => {
  const state = createState(1);
  const top = brickAt(state, 3, 2); // y=132..152
  const bottom = brickAt(state, 4, 2); // y=160..180, gap [152,160]
  const cx = top.x + top.w / 2; // 200
  state.ball = {
    x: cx, y: 156, r: BALL_R, vx: 0, vy: -260,
    px: cx, py: 156,
  };
  collideBricks(state);
  assert.equal(Math.sign(state.ball.vy), DOWN, 'one flip: UP -> DOWN');
  assert.equal(top.alive, false);
  assert.equal(bottom.alive, false);
  assert.equal(collides(state.ball, bottom), false);
});

// --- D5: tunneling ----------------------------------------------------------

test('D5: a step longer than the brick is still caught (swept)', () => {
  const state = createState(6); // ballSpeed(6) = 710
  const brick = brickAt(state, 0, 2); // top row: y=48..68, x=164..236
  const cx = brick.x + brick.w / 2; // 200
  const dt = 0.05;
  // 710*0.05 = 35.5px > BRICK_H + 2*BALL_R = 34: one step clears the brick.
  // Both endpoints are clear of it, so a positional check misses it entirely.
  state.ball = {
    x: cx,
    y: brick.y + brick.h + BALL_R, // 75, past the brick
    r: BALL_R, vx: 0, vy: ballSpeed(6),
    px: cx, py: brick.y + brick.h + BALL_R - ballSpeed(6) * dt, // 39.5, above
  };
  assert.equal(collides(state.ball, brick), false, 'end position is past the brick');
  const broken = collideBricks(state);
  assert.equal(broken, 1);
  assert.equal(brick.alive, false);
  assert.ok(state.ball.vy < 0, 'must bounce back up');
  assert.equal(collides(state.ball, brick), false);
});

// --- D6: paddle -------------------------------------------------------------

test('D6a: ball clipping the paddle corner still bounces', () => {
  const state = createState(1);
  state.ball = {
    x: state.paddle.x - 4, y: state.paddle.y - BALL_R, r: BALL_R, vx: 0, vy: 260,
  };
  step(state, 1 / 60);
  assert.ok(state.ball.vy < 0, 'descending ball must bounce off the paddle');
  assert.equal(state.ball.y, state.paddle.y - BALL_R);
});

test('D6b: fast ball crossing the whole paddle band still bounces', () => {
  const state = createState(2); // level 2: 350*0.05 = 17.5px > 12px band
  state.ball = {
    x: state.paddle.x + state.paddle.w / 2, y: state.paddle.y - BALL_R, r: BALL_R, vx: 0, vy: 350,
  };
  step(state, 0.05);
  assert.ok(state.ball.vy < 0, 'must bounce off the paddle');
  assert.equal(state.ball.y, state.paddle.y - BALL_R);
});

// --- D7: dead angle ---------------------------------------------------------

test('D7: dead-center paddle hit keeps a playable angle', () => {
  const state = createState(1);
  state.ball = {
    x: state.paddle.x + state.paddle.w / 2, y: state.paddle.y - BALL_R - 2, r: BALL_R, vx: 0, vy: 260,
  };
  step(state, 1 / 60);
  assert.ok(state.ball.vy < 0);
  assert.ok(
    Math.abs(state.ball.vx) >= 0.09 * ballSpeed(1) - 1e-9,
    `|vx| must not vanish (got ${state.ball.vx})`,
  );
});

// --- D8: speed conservation -------------------------------------------------

test('D8: rebound speed is the level speed, not the arrival speed', () => {
  const state = createState(1);
  state.ball = {
    x: state.paddle.x + state.paddle.w / 2 + 10, y: state.paddle.y - BALL_R - 2,
    r: BALL_R, vx: 100, vy: 500,
  };
  step(state, 1 / 60);
  assert.ok(state.ball.vy < 0);
  const v = Math.hypot(state.ball.vx, state.ball.vy);
  assert.ok(Math.abs(v - ballSpeed(1)) < 1e-9, `|v| = ${v} must equal the level speed ${ballSpeed(1)}`);
});

