    const state = createState(6); // ballSpeed(6) = 710
    const brick = state.bricks[0 * 8 + 2]; // rangée 0 : y=48..68, x=164..236
    const cx = brick.x + brick.w / 2; // 200
    const dt = 0.05;
    // 710*0.05 = 35.5 px > BRICK_H + 2*BALL_R = 34 : la balle franchit la brique en un pas.
    state.ball = { x: cx, y: brick.y + brick.h + BALL_R, r: BALL_R, vx: 0, vy: ballSpeed(6), px: cx, py: brick.y + brick.h + BALL_R - ballSpeed(6) * dt };
    assert.equal(collides(state.ball, brick), false, 'end position is past the brick');
    const broken = collideBricks(state);
    assert.equal(broken, 1);
    assert.equal(brick.alive, false);
    assert.ok(state.ball.vy < 0, 'must bounce back up');
    assert.equal(collides(state.ball, brick), false);
  });
  ```
- **Rouge aujourd'hui** : `AssertionError [ERR_ASSERTION]: Expected values to be strictly equal: actual: true, expected: false` — la brique traversée reste vivante (le détecteur positionnel ne la voit pas ; seule la brique de la rangée suivante, chevauchée par la position finale, est cassée).
- **Discrimine** : refuse la correction naïve « `collides` sur la position finale puis inversion » : la position finale ne recouvre pas la brique → aucun rebond, brique vivante.
- **Vert quand** : la collision est détectée par balayage du segment (position précédente → position courante) contre la boîte gonflée du rayon ; la brique meurt et la balle rebondit.
- **Révélé par** : D1 (invisible sans rebond ; ne se montre qu'au niveau ≥ 6 ou à 20 fps).

