// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls and the paddle. Does NOT handle bricks: that responsibility lives
// in `collideBricks()` (called from `frame()`).
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;

  // Keep the pre-step position: the brick and paddle passes sweep the segment
  // (px,py)->(x,y) so that no obstacle is jumped, whatever the step length.
  ball.px = ball.x;
  ball.py = ball.y;

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

  // Side walls
  if (ball.x - ball.r < 0) {
    ball.x = ball.r;
    ball.vx = Math.abs(ball.vx);
  } else if (ball.x + ball.r > WIDTH) {
    ball.x = WIDTH - ball.r;
    ball.vx = -Math.abs(ball.vx);
  }

  // Ceiling
  if (ball.y - ball.r < 0) {
    ball.y = ball.r;
    ball.vy = Math.abs(ball.vy);
  }

  // Paddle — swept circle-vs-rect test on the segment covered this step: a
  // descending ball always comes out through the top, even when it clips a
  // corner or would jump the 12px band in a single step (tunneling).
  if (ball.vy > 0 && sweptHit(ball, paddle)) {
    ball.y = paddle.y - ball.r;
    // Rebound angle from the hit position; clamped to a playable minimum so
    // a dead-center hit never gives vx = 0 (the ball would loop vertically).
    const speed = ballSpeed(state.level);
    let hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
    hit = Math.max(-1, Math.min(1, hit));
    if (Math.abs(hit) < 0.15) hit = hit < 0 ? -0.15 : 0.15;
    ball.vx = speed * 0.6 * hit;
    // Renormalize to the level speed: the rebound speed is the level's, not
    // the arrival speed (a fast crooked ball must not keep its old |v|).
    ball.vy = -speed * Math.sqrt(1 - (0.6 * hit) ** 2);
    state.combo = 0; // touching the paddle resets the combo
  }

  // Exit through the bottom: ball lost
  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;
}
```

