```js
// Resolves ball/brick collisions for one step (bricks broken, score/combo
// updated, ball deflected). The ball's position at the START of the step must
// be stored on `ball.px`/`ball.py` (step() does it): the pass sweeps the
// segment (px,py)->(x,y) against every live brick, so a step longer than a
// brick is still caught (no tunneling) and the face hit is the real one.
// Bricks are resolved in order of entry time; each velocity axis flips at most
// once per pass, so a ball squeezed on a grid seam (gap 8px < ball 14px) is
// deflected once, never twice. Returns the number of bricks broken.
export function collideBricks(state) {
  const { ball, bricks } = state;
  let flippedX = false;
  let flippedY = false;
  let broken = 0;
  // Fixpoint: each iteration kills one brick, so the loop terminates.
  for (let i = 0; i <= bricks.length; i++) {
    let best = null;
    for (const brick of bricks) {
      if (!brick.alive) continue;
      const hit = sweptHit(ball, brick);
      if (hit && (best === null || hit.t < best.t)) best = { brick, ...hit };
    }
    if (!best) break;
    const { brick, t, axis } = best;
    const face = exitFace(ball, brick, t, axis);
    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);
    broken += 1;
    if (face === 'left' || face === 'right') {
      if (!flippedX) { ball.vx = -ball.vx; flippedX = true; }
    } else if (face === 'top' || face === 'bottom') {
      if (!flippedY) { ball.vy = -ball.vy; flippedY = true; }
    } else {
      if (!flippedX) { ball.vx = -ball.vx; flippedX = true; }
      if (!flippedY) { ball.vy = -ball.vy; flippedY = true; }
    }
    pushOut(ball, brick, face);
  }
  return broken;
}
```

