// True if the ball (circle approximated by its box) overlaps the brick.
// Simple AABB test: it only says WHETHER the ball and the brick overlap, not
// WHICH face was hit. The per-step bounce lives in collideBricks() below.
export function collides(ball, brick) {
  return (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

// Which axis of `rect` the ball overlaps, by smallest penetration. Equal
// penetration on both axes means we are exactly on a corner: both velocities
// flip (face-vs-corner rule). Returns 'x', 'y' or 'both'.
function penetrationAxis(ball, rect) {
  const penX = Math.min(ball.x + ball.r - rect.x, rect.x + rect.w - (ball.x - ball.r));
  const penY = Math.min(ball.y + ball.r - rect.y, rect.y + rect.h - (ball.y - ball.r));
  if (penX === penY) return 'both';
  return penX < penY ? 'x' : 'y';
}

// Swept circle-vs-AABB: does the ball's segment (px,py)->(x,y) cross `rect`
// inflated by the ball radius? Returns the earliest entry { t, axis } with
// axis 'x' | 'y' | 'both' (a corner), or null. `t` is the fraction of the
// segment at which the ball first touches the inflated box: a t > 0 means the
// discrete check at the end position would have MISSED the collision
// (tunneling); a t = 0 means the ball already overlaps it.
function sweptHit(ball, rect) {
  const left = rect.x - ball.r;
  const right = rect.x + rect.w + ball.r;
  const top = rect.y - ball.r;
  const bottom = rect.y + rect.h + ball.r;
  const x0 = ball.px ?? ball.x;
  const y0 = ball.py ?? ball.y;
  const x1 = ball.x;
  const y1 = ball.y;
  const dx = x1 - x0;
  const dy = y1 - y0;

  if (dx === 0 && dy === 0) {
    const inside = x1 >= left && x1 <= right && y1 >= top && y1 <= bottom;
    return inside ? { t: 0, axis: penetrationAxis(ball, rect) } : null;
  }

  // Liang-Barsky slab test: per-axis entry/exit times into the inflated box.
  let tmin = 0;
  let tmax = 1;
  let entryAxis = null;
  if (dx === 0) {
    if (x0 < left || x0 > right) return null;
  } else {
    let t1 = (left - x0) / dx;
    let t2 = (right - x0) / dx;
    if (t1 > t2) [t1, t2] = [t2, t1];
    if (t1 > tmin) { tmin = t1; entryAxis = 'x'; }
    if (t2 < tmax) tmax = t2;
  }
  if (dy === 0) {
    if (y0 < top || y0 > bottom) return null;
  } else {
    let t1 = (top - y0) / dy;
    let t2 = (bottom - y0) / dy;
    if (t1 > t2) [t1, t2] = [t2, t1];
    if (t1 > tmin) { tmin = t1; entryAxis = 'y'; }
    if (t2 < tmax) tmax = t2;
  }
  if (tmax < tmin || tmax < 0 || tmin > 1) return null;
  // When the entry happened before this step started (tmin stays 0), the
  // entry slab is meaningless: fall back to the penetration rule.
  const axis = tmin > 0 ? entryAxis : penetrationAxis(ball, rect);
  return { t: tmin, axis };
}

// Which face of `rect` the ball must exit from: for a swept entry (t > 0) it
// is the face the segment crossed; for an overlap (t = 0) it is the nearest
// face, so the ball is pushed out of the rectangle (never left inside).
function exitFace(ball, rect, t, axis) {
  if (t > 0) {
    if (axis === 'x') return ball.x - ball.px > 0 ? 'left' : 'right';
    return ball.y - ball.py > 0 ? 'top' : 'bottom';
  }
  if (axis === 'both') return 'both';
  if (axis === 'x') {
    return Math.abs(ball.x - rect.x) <= Math.abs(rect.x + rect.w - ball.x) ? 'left' : 'right';
  }
  return Math.abs(ball.y - rect.y) <= Math.abs(rect.y + rect.h - ball.y) ? 'top' : 'bottom';
}

// Places the ball just outside `rect` on the given face ('both' = corner).
function pushOut(ball, rect, face) {
  if (face === 'top') ball.y = rect.y - ball.r;
  else if (face === 'bottom') ball.y = rect.y + rect.h + ball.r;
  else if (face === 'left') ball.x = rect.x - ball.r;
  else if (face === 'right') ball.x = rect.x + rect.w + ball.r;
  else {
    // Corner: exit diagonally, on the nearest side of each axis.
    ball.x = ball.x < rect.x + rect.w / 2 ? rect.x - ball.r : rect.x + rect.w + ball.r;
    ball.y = ball.y < rect.y + rect.h / 2 ? rect.y - ball.r : rect.y + rect.h + ball.r;
  }
}

// Resolves ball/brick collisions for one step: breaks bricks, updates
// score/combo and deflects the ball. The ball's position at the START of the
// step must be stored on ball.px/ball.py (step() does it): the pass sweeps
// the segment (px,py)->(x,y) against every live brick, so a step longer than
// a brick is still caught (no tunneling, D5) and the face hit is the real
// one (D3). Bricks are resolved in order of entry time and each velocity axis
// flips at most once per pass, so a ball squeezed on a grid seam (gap 8px <
// ball diameter 14px) is deflected once, never twice (D4). The ball is always
// pushed out of the brick it touched (D2). Returns the number of bricks broken.
export function collideBricks(state) {
  const { ball, bricks } = state;
  let flippedX = false;
  let flippedY = false;
  let broken = 0;
  // Fixpoint: each iteration breaks one brick, so the loop terminates.
  for (let i = 0; i <= bricks.length; i++) {
    let best = null;
    for (const brick of bricks) {
      if (!brick.alive) continue;
      const hit = sweptHit(ball, brick);
      if (hit && (best === null || hit.t < best.t)) best = { brick, ...hit };
    }
    if (!best) break;
    const { brick, t, axis } = best;
    const face = exitFace(ball, brick, t, axis);
    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);
    broken += 1;
    if (face === 'left' || face === 'right') {
      if (!flippedX) { ball.vx = -ball.vx; flippedX = true; }
    } else if (face === 'top' || face === 'bottom') {
      if (!flippedY) { ball.vy = -ball.vy; flippedY = true; }
    } else {
      if (!flippedX) { ball.vx = -ball.vx; flippedX = true; }
      if (!flippedY) { ball.vy = -ball.vy; flippedY = true; }
    }
    pushOut(ball, brick, face);
  }
  return broken;
}

