+// Which axis of `rect` the ball overlaps, by smallest penetration. Equal
+// penetration on both axes means we are exactly on a corner: both velocities
+// flip (face-vs-corner rule). Returns 'x', 'y' or 'both'.
+function penetrationAxis(ball, rect) {
+  const penX = Math.min(ball.x + ball.r - rect.x, rect.x + rect.w - (ball.x - ball.r));
+  const penY = Math.min(ball.y + ball.r - rect.y, rect.y + rect.h - (ball.y - ball.r));
+  if (penX === penY) return 'both';
+  return penX < penY ? 'x' : 'y';
+}
+
+// Swept circle-vs-AABB: does the ball's segment (px,py)->(x,y) cross `rect`
+// inflated by the ball radius? Returns the earliest entry { t, axis } with
+// axis 'x' | 'y' | 'both' (a corner), or null. `t` is the fraction of the
+// segment at which the ball first touches the inflated box: a t > 0 means the
+// discrete check at the end position would have MISSED the collision
+// (tunneling); a t = 0 means the ball already overlaps it.
+function sweptHit(ball, rect) {
+  const left = rect.x - ball.r;
+  const right = rect.x + rect.w + ball.r;
+  const top = rect.y - ball.r;
+  const bottom = rect.y + rect.h + ball.r;
+  const x0 = ball.px ?? ball.x;
+  const y0 = ball.py ?? ball.y;
+  const x1 = ball.x;
+  const y1 = ball.y;
+  const dx = x1 - x0;
+  const dy = y1 - y0;
+
+  if (dx === 0 && dy === 0) {
+    const inside = x1 >= left && x1 <= right && y1 >= top && y1 <= bottom;
+    return inside ? { t: 0, axis: penetrationAxis(ball, rect) } : null;
+  }
+
+  // Liang-Barsky slab test: per-axis entry/exit times into the inflated box.
+  let tmin = 0;
+  let tmax = 1;
+  let entryAxis = null;
+  if (dx === 0) {
+    if (x0 < left || x0 > right) return null;
+  } else {
+    let t1 = (left - x0) / dx;
+    let t2 = (right - x0) / dx;
+    if (t1 > t2) [t1, t2] = [t2, t1];
+    if (t1 > tmin) { tmin = t1; entryAxis = 'x'; }
+    if (t2 < tmax) tmax = t2;
+  }
+  if (dy === 0) {
+    if (y0 < top || y0 > bottom) return null;
+  } else {
+    let t1 = (top - y0) / dy;
+    let t2 = (bottom - y0) / dy;
+    if (t1 > t2) [t1, t2] = [t2, t1];
+    if (t1 > tmin) { tmin = t1; entryAxis = 'y'; }
+    if (t2 < tmax) tmax = t2;
+  }
+  if (tmax < tmin || tmax < 0 || tmin > 1) return null;
+  // When the entry happened before this step started (tmin stays 0), the
+  // entry slab is meaningless: fall back to the penetration rule.
+  const axis = tmin > 0 ? entryAxis : penetrationAxis(ball, rect);
+  return { t: tmin, axis };
+}
+
+// Which face of `rect` the ball must exit from: for a swept entry (t > 0) it
+// is the face the segment crossed; for an overlap (t = 0) it is the nearest
+// face, so the ball is pushed out of the rectangle (never left inside).
+function exitFace(ball, rect, t, axis) {
+  if (t > 0) {
+    if (axis === 'x') return ball.x - ball.px > 0 ? 'left' : 'right';
+    return ball.y - ball.py > 0 ? 'top' : 'bottom';
+  }
+  if (axis === 'both') return 'both';
+  if (axis === 'x') {
+    return Math.abs(ball.x - rect.x) <= Math.abs(rect.x + rect.w - ball.x) ? 'left' : 'right';
+  }
+  return Math.abs(ball.y - rect.y) <= Math.abs(rect.y + rect.h - ball.y) ? 'top' : 'bottom';
+}
