+// Places the ball just outside `rect` on the given face ('both' = corner).
+function pushOut(ball, rect, face) {
+  if (face === 'top') ball.y = rect.y - ball.r;
+  else if (face === 'bottom') ball.y = rect.y + rect.h + ball.r;
+  else if (face === 'left') ball.x = rect.x - ball.r;
+  else if (face === 'right') ball.x = rect.x + rect.w + ball.r;
