test('D6a: ball clipping the paddle corner still bounces', () => {
  const state = createState(1);
  state.ball = {
    x: state.paddle.x - 4, y: state.paddle.y - BALL_R, r: BALL_R, vx: 0, vy: 260,
  };
  step(state, 1 / 60);
  assert.ok(state.ball.vy < 0, 'descending ball must bounce off the paddle');
