});

test('D6b: fast ball crossing the whole paddle band still bounces', () => {
  const state = createState(2); // level 2: 350*0.05 = 17.5px > 12px band
  state.ball = {
    x: state.paddle.x + state.paddle.w / 2, y: state.paddle.y - BALL_R, r: BALL_R, vx: 0, vy: 350,
  };
  step(state, 0.05);
  assert.ok(state.ball.vy < 0, 'must bounce off the paddle');
  assert.equal(state.ball.y, state.paddle.y - BALL_R);
});

test('D7: dead-center paddle hit keeps a playable angle', () => {
  const state = createState(1);
  state.ball = {
    x: state.paddle.x + state.paddle.w / 2, y: state.paddle.y - BALL_R - 2, r: BALL_R, vx: 0, vy: 260,
  };
  step(state, 1 / 60);
  assert.ok(state.ball.vy < 0);
