  );
});

test('D8: rebound speed is the level speed, not the arrival speed', () => {
  const state = createState(1);
  state.ball = {
    x: state.paddle.x + state.paddle.w / 2 + 10, y: state.paddle.y - BALL_R - 2,
    r: BALL_R, vx: 100, vy: 500,
  };
  step(state, 1 / 60);
  assert.ok(state.ball.vy < 0);
  const v = Math.hypot(state.ball.vx, state.ball.vy);
  assert.ok(Math.abs(v - ballSpeed(1)) < 1e-9, `|v| = ${v} must equal the level speed ${ballSpeed(1)}`);
});

